 $('#dangerText').textContent=state.time<=45&&state.phase==='playing'?'SUDDEN DEATH · STAY INSIDE THE RING':'';
 const ctx=$<HTMLCanvasElement>('#minimap').getContext('2d')!;ctx.clearRect(0,0,160,160);ctx.fillStyle='rgba(35,37,46,.55)';ctx.beginPath();ctx.roundRect(0,0,160,160,20);ctx.fill();ctx.strokeStyle='#f5ead27a';ctx.lineWidth=1;ctx.strokeRect(8,8,144,144);
 const goalScore=$('#goalScore');if(goalScore)goalScore.innerHTML=state.ctf?`<span class="blue">BLUE ${state.ctf.scores[0]}</span> : <span class="orange">${state.ctf.scores[1]} ORANGE</span><small>CAPTURE = ONE BALLOON PER RIVAL</small><small>${state.ctf.flags.map(f=>f.team.toUpperCase()+': '+(f.home?'HOME':f.carrier!==null?'CARRIED BY '+esc(state.karts.find(k=>k.id===f.carrier)?.name??'?'):'DROPPED · '+Math.ceil(f.returnIn)+'s')).join(' · ')}</small>`:state.ball?`<span class="blue">BLUE ${state.ball.goals[0]}</span> : <span class="orange">${state.ball.goals[1]} ORANGE</span><small>${state.ball.respawn>0?'BALL RETURNS TO MIDFIELD':'GOAL = ONE BALLOON PER DEFENDER'}</small>`:'';
 const mapScale=72/arenaExtent(state.config.arena);if(state.ball&&state.config.soccer){for(const sign of [-1,1]){ctx.fillStyle=sign>0?'#62b8ff':'#ff9c52';ctx.fillRect(80-18*mapScale,80+sign*116*mapScale-2,36*mapScale,4);}}if(state.ball&&state.ball.respawn<=0){ctx.fillStyle='#ffffff';ctx.strokeStyle='#1b273b';ctx.beginPath();ctx.arc(80+state.ball.x*mapScale,80+state.ball.z*mapScale,3,0,Math.PI*2);ctx.fill();ctx.stroke();}
